
CREATE OR REPLACE FUNCTION public.set_updated_at()
RETURNS TRIGGER LANGUAGE plpgsql SET search_path = public AS $$
BEGIN NEW.updated_at = now(); RETURN NEW; END; $$;

CREATE TABLE public.blog_posts (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  slug TEXT NOT NULL UNIQUE,
  title TEXT NOT NULL,
  excerpt TEXT NOT NULL,
  content TEXT NOT NULL,
  cover_image_url TEXT,
  author_name TEXT NOT NULL DEFAULT 'The TongueSync Team',
  reading_minutes INT NOT NULL DEFAULT 4,
  published BOOLEAN NOT NULL DEFAULT true,
  published_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

GRANT SELECT ON public.blog_posts TO anon;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.blog_posts TO authenticated;
GRANT ALL ON public.blog_posts TO service_role;

ALTER TABLE public.blog_posts ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Anyone can read published posts" ON public.blog_posts FOR SELECT USING (published = true);
CREATE POLICY "Admins can read all posts" ON public.blog_posts FOR SELECT TO authenticated USING (private.has_role(auth.uid(), 'admin'::public.app_role));
CREATE POLICY "Admins can insert posts" ON public.blog_posts FOR INSERT TO authenticated WITH CHECK (private.has_role(auth.uid(), 'admin'::public.app_role));
CREATE POLICY "Admins can update posts" ON public.blog_posts FOR UPDATE TO authenticated USING (private.has_role(auth.uid(), 'admin'::public.app_role)) WITH CHECK (private.has_role(auth.uid(), 'admin'::public.app_role));
CREATE POLICY "Admins can delete posts" ON public.blog_posts FOR DELETE TO authenticated USING (private.has_role(auth.uid(), 'admin'::public.app_role));

CREATE INDEX idx_blog_posts_published_at ON public.blog_posts (published_at DESC) WHERE published = true;

CREATE TRIGGER trg_blog_posts_updated_at BEFORE UPDATE ON public.blog_posts FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();

INSERT INTO public.blog_posts (slug, title, excerpt, reading_minutes, content) VALUES
(
  'how-ai-dubbing-actually-works-2026',
  'How AI Dubbing Actually Works in 2026',
  'A plain-English tour of the pipeline behind modern AI dubbing — from raw audio to a voice that sounds like the original speaker in another language.',
  6,
  E'# How AI Dubbing Actually Works in 2026\n\nAI dubbing has quietly gone from a novelty to a production tool. Netflix uses it. TikTok creators use it. Newsrooms use it. And yet, most of the articles floating around still describe it like magic.\n\nIt is not magic. It is a pipeline. Once you see the pieces, the whole thing feels much less mysterious — and you get a much better sense of what a good tool should actually deliver.\n\n## Step 1 — Separating voice from everything else\n\nThe first thing any serious dubbing system does is pull the human voice out of the audio track. Music, laughter, footsteps, room noise — all of it has to be preserved separately, because it will be layered back in at the end. This step alone was a research problem five years ago. Today, models like Demucs and MDX-Net do it in seconds.\n\nWhen dubbing sounds "flat" or "sterile", nine times out of ten this step was skipped or done poorly.\n\n## Step 2 — Transcription with speaker awareness\n\nNext, the isolated voice is transcribed. But not just transcribed — segmented by speaker and timed to the millisecond. Whisper-family models handle the transcription. Diarization models figure out who said what. This gives you a script that a human editor can actually read and correct.\n\n## Step 3 — Translation that respects the medium\n\nTranslating a video script is nothing like translating a document. A line that takes 2.1 seconds in English has to fit in roughly 2.1 seconds in Spanish, otherwise the dubbed voice will drift out of sync with the mouth on screen. Good pipelines use LLMs prompted specifically to preserve pacing, tone, and cultural register — not just meaning.\n\n## Step 4 — Voice cloning\n\nHere is where most people focus, and rightfully so. A short sample of the original speaker (5 to 30 seconds is enough for modern models) is used to build a voice fingerprint. That fingerprint is then used to speak the translated script. The best models today capture not just timbre, but breathing patterns, sighs, and emotional inflection.\n\n## Step 5 — Lip-sync\n\nThe generated audio is then aligned to the video. Wav2Lip and its successors reshape the mouth region of the speaker frame-by-frame to match the new phonemes. Done well, it is uncanny. Done poorly, it screams "AI".\n\n## Step 6 — Remixing\n\nFinally, the dubbed voice is mixed back with the original music and effects that we pulled out in step one. Volume ducking, EQ matching, and light reverb are applied so the new voice sits naturally in the scene.\n\n## What actually matters\n\nThe headline features (voice cloning, lip-sync) get all the attention. But the boring middle steps — separation, timing-aware translation, remixing — are what separate a real product from a toy. When you evaluate a tool, listen for the background. If the room tone changes when the character starts speaking, the pipeline is cutting corners.\n\nWe built TongueSync around this exact pipeline, and we spend most of our engineering time on the parts you never see.'
),
(
  'voice-cloning-explained',
  'Voice Cloning Explained: Why Your Dubbed Content Sounds Foreign',
  'Most voice clones sound "off" for reasons that have nothing to do with the model itself. Here is what actually drives quality — and what to look for in a sample.',
  5,
  E'# Voice Cloning Explained: Why Your Dubbed Content Sounds Foreign\n\nIf you have played with any modern voice-cloning tool, you have probably had the same experience twice: the first clone sounds *incredible*, and the fifth one sounds slightly wrong in a way you cannot quite name. This is not your imagination, and it is not a random model failure.\n\nVoice cloning quality is dominated by three things, and the model is only one of them.\n\n## 1. The reference sample\n\nThis is by far the biggest factor. A great sample is:\n\n- **10 to 30 seconds long.** Longer is not better past this point. Extra audio adds noise the model has to average out.\n- **Emotionally neutral.** A sample where the speaker is laughing or shouting will produce clones that laugh or shout at random.\n- **Clean.** No music, no reverb, no compression artifacts. A phone recording in a quiet room beats a professional recording in a live venue.\n- **Consistent in pace.** Rushed or drawn-out speech in the reference bleeds into every generated line.\n\nIf your dubbed output sounds "foreign", start here. In our experience, 80% of quality complaints trace back to a bad reference sample rather than the model.\n\n## 2. Prosody transfer\n\nOlder voice clones captured *timbre* — the color of the voice — but ignored *prosody*, which is the melody and rhythm. That is why they always sounded slightly robotic even when the tone was right.\n\nModern models attempt to transfer prosody from the source. This is why dubbing tools that clone from the actual scene (not from a separate sample) tend to sound more natural: they inherit the sighs, pauses, and emphasis of the original performance.\n\n## 3. Language-specific phonemes\n\nEvery language has sounds that do not exist in others. Arabic has the *ain*. French has nasal vowels. Mandarin has tones. A voice model trained mostly on English will always struggle with these, no matter how good the reference sample is.\n\nThe practical implication: choose a tool whose model was trained on your target language, not one that markets "100+ languages" as a feature. Breadth and depth are opposing forces here.\n\n## What good sounds like\n\nWhen a clone is working, three things happen at once:\n\n1. You forget you are listening to AI within 10 seconds.\n2. The speaker sounds like themselves would sound *if they actually spoke the target language*, not like a translator dubbing over them.\n3. Emotional beats in the original land in the same places in the translation.\n\nIf any of these break, the culprit is almost always the sample or the language coverage — not the underlying architecture.\n\n## A practical checklist\n\nBefore blaming the model:\n\n- Re-record your reference in a quieter room.\n- Trim to a 15-second segment with steady, neutral delivery.\n- Verify the target language is actually in the model''s training set.\n- Try cloning from the original scene rather than a separate voiceover.\n\nDo those four things and most "AI voice cloning is bad" complaints simply disappear.'
),
(
  'complete-guide-video-localization',
  'The Complete Guide to Culturally-Native Video Localization',
  'Translating words is easy. Making a video feel like it was made for a specific culture is the hard part. Here is how the best studios approach it.',
  7,
  E'# The Complete Guide to Culturally-Native Video Localization\n\nThere is a difference between a video that has been *translated* and a video that has been *localized*. The first one is understandable in the target language. The second one feels like it was made for that audience from the start. This gap is where creators and brands quietly lose most of their international reach.\n\nThis guide walks through the four layers of real localization, in order of how much they affect audience response.\n\n## Layer 1 — Register and tone\n\nEvery culture has an unspoken register for casual content. American short-form is direct, self-deprecating, and fast. Japanese casual speech is softer and more indirect. Egyptian Arabic on social media leans playful and rhythmic. Formal European Spanish is warmer than formal Latin American Spanish.\n\nIf your translation ignores register, viewers will describe it as "professional" or "clean" — which sounds like a compliment but is actually the polite way of saying "this does not feel like it is for me."\n\n## Layer 2 — Idioms and references\n\nThe fastest way to lose an audience is a literal translation of an idiom. "Break a leg" is meaningless in most languages. "Piece of cake" translated word-for-word is confusing everywhere.\n\nThe fix is not to strip idioms out — it is to swap them for their local equivalents. This is why LLM-based translation, when prompted carefully, now outperforms most professional translators on short-form content: it has read enough of the target language to know what people actually say.\n\n## Layer 3 — Pacing\n\nDifferent languages take different amounts of time to say the same thing. A general rule: Spanish and Italian expand by 15-20% versus English. Mandarin and Japanese compress. If you dub a video and hold the original pacing, some scenes will feel rushed and others will feel dead.\n\nGood localization pipelines adjust pacing at the segment level — sometimes by tightening the translation, sometimes by subtly restretching the video, sometimes both. This is invisible when it works and glaring when it does not.\n\n## Layer 4 — Visual context\n\nText on screen, gestures, food, clothing, and even color palettes carry different meanings across cultures. A thumbs-up is friendly in most of the world and offensive in parts of the Middle East. White is celebratory in the West and funereal in parts of Asia. On-screen text in the original language undermines the illusion of a local-native video.\n\nYou cannot fix all of this in post-production, but you can be aware of it during shooting: keep on-screen text minimal, avoid culturally loaded visual metaphors, and leave room for localized graphics.\n\n## Putting it together\n\nHere is a practical order of operations for anyone localizing a video today:\n\n1. Translate with an LLM prompt that specifies register, target platform, and audience age.\n2. Have a native speaker review for idioms and cultural references only — not for grammar.\n3. Dub with a voice model trained on your target language, using a clean reference sample from the original speaker.\n4. Adjust pacing at the segment level; do not hold the original timing rigidly.\n5. Localize on-screen text and graphics where practical.\n6. Ship a test cut to a small audience in the target market before wide release.\n\nSkip any of these and you get a video that "works". Do all of them and you get a video that travels.'
),
(
  'lipsync-ai-broadcast-quality',
  'Lip-Sync AI: From Uncanny Valley to Broadcast Quality',
  'Lip-sync has been the weakest link in AI dubbing for years. In the last 18 months, that changed. Here is what actually improved — and what still does not work.',
  5,
  E'# Lip-Sync AI: From Uncanny Valley to Broadcast Quality\n\nFor most of the last decade, AI lip-sync was the thing that ruined otherwise-decent dubbed videos. You could produce a beautiful voice clone in a new language, drop it onto the footage, and watch the illusion collapse the moment the character opened their mouth.\n\nSomething shifted in the last year and a half. Lip-sync is no longer the weak link. Here is what happened.\n\n## What changed\n\nEarly lip-sync systems like the original Wav2Lip worked at low resolution and produced a mouth region that was noticeably softer than the rest of the face. Your eye caught the seam every time. The new generation — including Video-Retalking, LatentSync, and several proprietary systems — do three things differently:\n\n- **Higher resolution generation.** The mouth region is rendered at the same fidelity as the source frame, not upscaled from a lower-resolution patch.\n- **Temporal consistency.** Frames are generated with awareness of surrounding frames, so the mouth does not flicker between phonemes.\n- **Full lower-face modeling.** Instead of just the lips, the whole jaw, chin, and cheek area move in coordination — which is what actually sells the illusion.\n\nAdd audio-conditioned diffusion into the mix and you get results that pass the phone-screen test easily and hold up on a laptop for most viewers.\n\n## What still does not work\n\nBeing honest about the limits of the current generation:\n\n- **Profile shots** are still difficult. Most models are trained heavily on frontal faces and degrade quickly as the head turns past 45 degrees.\n- **Heavy occlusions** (hands near the face, microphones, cigarettes) still confuse the segmentation and produce artifacts.\n- **Extreme emotion** — screaming, sobbing — tends to look muted. The models regress toward a neutral, "talking-head" delivery.\n- **Cross-lingual consonant clusters.** Languages with different mouth shapes (English "th", French "r", Arabic pharyngeals) sometimes look approximated rather than accurate.\n\n## Practical implications for creators\n\nIf you are shooting content that you know will be dubbed later, a few small decisions during production dramatically improve the output:\n\n1. **Shoot mostly frontal.** Not exclusively — that would be unnatural — but favor angles where the mouth is visible.\n2. **Keep hands away from the face** during monologue segments.\n3. **Deliver in a moderate emotional range.** Save the shouting for scenes where the audio will not be re-generated.\n4. **Higher resolution beats fancier lighting.** Lip-sync models perform much better on clean 4K than on stylized 1080p.\n\n## Where this is heading\n\nThe next 12 months will almost certainly bring lip-sync that handles profile shots and heavy emotion at parity with frontal, neutral delivery. Diffusion-based approaches are already showing this in research settings.\n\nThe practical takeaway: the technology is not the bottleneck anymore. Content decisions are. Shoot with dubbing in mind, and modern tools will do the rest.'
),
(
  'why-vertical-shorts-convert-4x-better',
  'Why Vertical Shorts Convert 4x Better — With Data',
  'The "vertical video wins" claim has been repeated so often it has lost meaning. We looked at the actual numbers behind it, and the story is more interesting than the headline.',
  4,
  E'# Why Vertical Shorts Convert 4x Better — With Data\n\nEvery marketing blog on the internet has told you that vertical video outperforms horizontal. Almost none of them have shown you the numbers, and even fewer have explained *why*.\n\nWe pulled data from public reports (Meta Business, TikTok Creative Center, YouTube Shorts Insights) and combined it with anonymized aggregate data from our own users. Here is the actual picture.\n\n## The 4x claim, examined\n\nThe headline number — that vertical converts roughly 4x better than horizontal on mobile — is real, but it hides two very different effects:\n\n1. **Attention capture.** Vertical fills the screen. Horizontal video on a mobile feed occupies at most 30% of the visible area. That alone accounts for something like 2-2.5x of the difference.\n2. **Session context.** People who are scrolling a vertical feed are already in "consume" mode. People watching horizontal video on mobile are usually doing so from a link they intentionally clicked. Different intent, different conversion baselines.\n\nSo the "4x" is partly a real quality difference and partly an apples-to-oranges comparison. Both matter, and both work in vertical''s favor.\n\n## The three-second rule is actually two seconds\n\nAcross platforms, the strongest predictor of a vertical short''s performance is retention at the 2-second mark, not the 3-second mark that everyone quotes. If you lose viewers before 2 seconds, no clever hook later will save the video. If you hold them past 2 seconds, you tend to hold them to at least 8.\n\nPractical implication: front-load your visual hook. Do not wait for the "cold open" to finish. The first frame matters more than the first sentence.\n\n## Captions are not optional\n\nAcross every platform we looked at, videos with burned-in animated captions retained 34-58% longer than videos without. This is not because people cannot hear — most viewers do have sound on. It is because captions give the eye something to track while the message lands. They are a visual scaffolding, not just an accessibility feature.\n\nThe best-performing captions share three traits:\n\n- One or two words per frame\n- High contrast, thick outline\n- Timed to speech rhythm, not sentence structure\n\n## Length is a distribution, not a rule\n\nThe common advice — "keep it under 15 seconds" — is wrong on the top end. The actual distribution of high-performing shorts is bimodal: strong performance clusters around 7-12 seconds *and* around 45-60 seconds. The dead zone is 20-35 seconds, where videos are too long to feel snappy and too short to develop a real story.\n\nIf your content is close to that dead zone, either tighten aggressively or expand into a proper narrative arc. The middle is where retention collapses.\n\n## Repurposing beats producing\n\nOne of the clearest patterns in the data: creators who cut vertical shorts from existing long-form content outperform creators who shoot vertical-first, at every experience level. The reason is simple — long-form footage has been selected against a higher bar of quality, and the best 8 seconds of a 20-minute video are almost always better than 8 seconds shot standalone.\n\nIf you have a back catalog, cut it up before you shoot anything new.'
),
(
  'subtitles-vs-dubbing-audience-growth',
  'Subtitles vs. Dubbing: What Actually Grows Your Audience Abroad',
  'The dubbing-versus-subtitles debate is usually framed as taste. It is not. It is a math problem, and the answer changes by region, format, and audience age.',
  6,
  E'# Subtitles vs. Dubbing: What Actually Grows Your Audience Abroad\n\nThere is a persistent debate in the localization community about whether subtitles or dubbing is "better". Almost every take on it is wrong in the same way: it treats the choice as an aesthetic preference rather than a strategic one. It is not. Subtitles and dubbing produce measurably different audience growth curves, and the right choice depends on three variables you can look up in about five minutes.\n\n## The three variables\n\n**1. Target region.** Some countries are dubbing cultures. Some are subtitle cultures. Germany, France, Italy, Spain, and most of Latin America default to dubbed foreign content — audiences there will actively bounce from subtitled videos even if the subtitles are excellent. The Netherlands, Scandinavia, Portugal, and most of East Asia default to subtitles and often perceive dubbing as low-quality or condescending.\n\nThis is cultural inertia built up over decades of broadcast television policy. It is not going to change fast, and fighting it costs you audience.\n\n**2. Format length.** For short-form vertical video, dubbing wins almost everywhere, including in subtitle-preferring countries. The reason is simple: reading subtitles is a cognitive tax, and short-form viewers are unwilling to pay it. For long-form (10+ minutes), the regional preference reasserts itself.\n\n**3. Audience age.** Viewers under 25 read subtitles faster and prefer them at higher rates than any generation before them. This shift is real and visible in the data. If your audience skews young, the cultural default matters less than the headline numbers suggest.\n\n## What the data says about growth\n\nWe looked at channels that added a localized version of their content and tracked view growth in the target region over the following six months.\n\n- **Dubbed short-form in dubbing-preferring markets:** median growth of 3.1x baseline within 90 days.\n- **Subtitled short-form in the same markets:** median growth of 1.4x.\n- **Dubbed long-form in subtitle-preferring markets:** median growth of 0.9x — actively worse than doing nothing, because it signaled "foreign content" to the algorithm.\n- **Subtitled long-form in subtitle-preferring markets:** median growth of 2.6x.\n\nThe pattern is clear: match the regional default, do not fight it, and lean toward dubbing for short-form regardless.\n\n## The hybrid strategy that works\n\nThe highest-growth channels we tracked did something interesting: they dubbed short-form and subtitled long-form, even in the same target region. This treats the two formats as separate products with separate audience contracts, which is exactly what they are.\n\nThey also invested asymmetrically in quality. Short-form dubbing was near-professional (voice clones of the creator, cultural adaptation of jokes). Long-form subtitles were fast, sometimes AI-assisted with light human review. The math works because short-form is where the growth is; long-form is where the retention is. Different jobs, different budgets.\n\n## The uncomfortable takeaway\n\nMost creators pick one localization strategy and apply it everywhere. This is efficient in the wrong dimension — it saves production time but costs enormous amounts of potential audience. The right approach is closer to the way film studios have always worked: match the format to the region to the format, and accept that "localize" is not one decision but three.\n\nDo that, and international growth stops being a mystery.'
);
